        raise TypeError(f'unexpected keyword arguments: {sorted(kw.keys())!r}')

    args_str = ', '.join(repr_func(arg) for arg in args)
    kwargs_str = ', '.join(f'{k}={repr_func(v)}' for k, v in kwargs.items())

    parts = [args_str, kwargs_str]
    parts = [p for p in parts if p]

    return f"{name}({', '.join(parts)})"
